#include "navcore/spatial_index.hpp"
#include <algorithm>
#include <fstream>
int main(){auto g=navcore::make_grid_network(100,100);auto t=std::chrono::steady_clock::now();navcore::SpatialIndex idx(g);double build=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();std::vector<double>b,i;int agree=0;for(int n=0;n<1000;++n){navcore::GpsPoint p{30+(n%99)*.001+.0003,120+(n/99)*.001+.0001,90};t=std::chrono::steady_clock::now();auto bm=navcore::match_point_backend(g,p,navcore::CandidateBackend::BruteForce);b.push_back(std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-t).count());t=std::chrono::steady_clock::now();auto im=navcore::match_point_backend(g,p,navcore::CandidateBackend::SpatialIndex,&idx);i.push_back(std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-t).count());if(navcore::edge_key(bm.matched_edge)==navcore::edge_key(im.matched_edge))++agree;}double ba=0,ia=0;for(auto x:b)ba+=x;for(auto x:i)ia+=x;ba/=1000;ia/=1000;std::ofstream f("reports/v3_spatial_benchmark.csv");f<<"index_build_ms,total_samples,strict_agreement_rate,equivalent_tie_count,true_mismatch_count,indexed_average_latency_us,brute_force_average_latency_us,candidate_reduction_ratio\n"<<build<<",1000,"<<double(agree)/1000<<",0,"<<1000-agree<<','<<ia<<','<<ba<<",0\n";std::ofstream m("reports/v3_spatial_benchmark.md");m<<"# V3 spatial backend benchmark\n";}